<?php
declare(strict_types=1);

$e = static fn (string $value): string => htmlspecialchars($value, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
$tab = in_array($_GET['tab'] ?? null, ['summary', 'attention', 'office', 'category', 'personnel'], true) ? $_GET['tab'] : 'summary';
$filters = $summary['filters'];
$exportQuery = http_build_query(array_filter($filters, static fn (mixed $value): bool => $value !== null && $value !== '' && $value !== false));
$exportSuffix = $exportQuery === '' ? '' : '?' . $exportQuery;
$pageQuery = $_GET;
unset($pageQuery['tab']);
$tabUrl = static fn (string $target): string => '/csi/reports?' . http_build_query([...$pageQuery, 'tab' => $target]);
$zone = new DateTimeZone('America/Lima');
$today = new DateTimeImmutable('today', $zone);
$quickUrl = static function (string $from, string $to) use ($pageQuery): string {
    unset($pageQuery['from'], $pageQuery['to']);
    return '/csi/reports?' . http_build_query([...$pageQuery, 'from' => $from, 'to' => $to]);
};
$start = isset($filters['from']) && is_string($filters['from']) ? new DateTimeImmutable($filters['from'], $zone) : $today->modify('-12 months');
$end = isset($filters['to']) && is_string($filters['to']) ? new DateTimeImmutable($filters['to'], $zone) : $today;
$intervalDays = max(1, (int) $start->diff($end)->days + 1);
$binCount = min(5, $intervalDays);
$bins = array_fill(0, $binCount, ['received' => 0, 'resolved' => 0, 'label' => '']);
for ($i = 0; $i < $binCount; $i++) {
    $from = $start->modify('+' . (int) floor($i * $intervalDays / $binCount) . ' days');
    $to = $start->modify('+' . ((int) floor(($i + 1) * $intervalDays / $binCount) - 1) . ' days');
    $bins[$i]['label'] = $from->format('d/m') . ($from->format('Y-m-d') === $to->format('Y-m-d') ? '' : '–' . $to->format('d/m'));
}
$areas = $categories = $people = $recent = [];
$resolved = $inProgress = $pending = 0;
if ($filterErrors === []) {
    foreach ($reports->rows($filters) as $row) {
        $status = $row['status_code'];
        $isResolved = in_array($status, ['resolved', 'closed'], true);
        if ($isResolved) { $resolved++; }
        if ($status === 'in_progress') { $inProgress++; }
        if ($status === 'pending') { $pending++; }
        $areaName = (string) $row['area_name'];
        $categoryName = (string) ($row['category_name'] ?? 'Sin clasificar');
        $personName = (string) ($row['technician_name'] ?? 'Sin asignar');
        $areas[$areaName] = ($areas[$areaName] ?? 0) + 1;
        $categories[$categoryName] = ($categories[$categoryName] ?? 0) + 1;
        $people[$personName] = ($people[$personName] ?? 0) + 1;
        if (count($recent) < 10) { $recent[] = $row; }
        $created = (new DateTimeImmutable($row['created_at']))->setTimezone($zone);
        $days = (int) $start->diff($created)->format('%r%a');
        if ($days >= 0 && $days < $intervalDays) {
            $index = min($binCount - 1, (int) floor($days * $binCount / $intervalDays));
            $bins[$index]['received']++;
            if ($isResolved) { $bins[$index]['resolved']++; }
        }
    }
}
arsort($areas); arsort($categories); arsort($people);
$maxBin = max(1, ...array_map(static fn (array $bin): int => max($bin['received'], $bin['resolved']), $bins));
$maxCategory = max(1, ...array_values($categories));
$maxArea = max(1, ...array_values($areas));
$statusColors = ['pending' => '#e8b451', 'in_progress' => '#3a86bb', 'resolved' => '#13958f', 'closed' => '#58ad9f', 'cancelled' => '#a28bc5'];
?>
<!doctype html><html lang="es-PE"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Reportes CSI | GRED Lambayeque</title><link rel="stylesheet" href="/assets/app.css?v=<?= (int) filemtime(dirname(__DIR__, 3) . '/public/assets/app.css') ?>"></head>
<body class="report-page min-h-screen bg-paper text-ink"><a href="#contenido" class="sr-only focus:not-sr-only">Saltar al contenido</a><header class="report-top"><a href="/dashboard">CSI · GRED</a><nav aria-label="Navegación"><a href="/dashboard">Vista general</a><a href="/csi/requests">Solicitudes</a><a href="/dashboard?section=team">Equipo y tareas</a><strong aria-current="page">Reportes</strong></nav></header>
<main id="contenido" class="report-content">
<header class="report-heading"><span aria-hidden="true">▥</span><div><h1>Reportes</h1><p>Analiza los resultados de las atenciones y genera informes de soporte tecnológico.</p></div></header>
<nav class="report-tabs" aria-label="Secciones del reporte"><?php foreach (['summary' => 'Resumen', 'attention' => 'Atenciones', 'office' => 'Por oficina', 'category' => 'Por tipo de problema', 'personnel' => 'Por personal'] as $key => $label): ?><a href="<?= $e($tabUrl($key)) ?>" <?= $tab === $key ? 'aria-current="page"' : '' ?>><?= $e($label) ?></a><?php endforeach; ?></nav>
<form method="get" action="/csi/reports" class="report-filters" aria-label="Filtros de reportes"><input type="hidden" name="tab" value="<?= $e($tab) ?>"><div class="report-filters__main"><div class="report-date"><label for="report-from">Período</label><div><input id="report-from" name="from" type="date" value="<?= $e((string) ($filters['from'] ?? '')) ?>" aria-label="Desde"><span>–</span><input name="to" type="date" value="<?= $e((string) ($filters['to'] ?? '')) ?>" aria-label="Hasta"></div></div><?php foreach (['area' => ['Oficina', 'areas'], 'technician' => ['Personal', 'technicians'], 'category' => ['Tipo de problema', 'categories'], 'status' => ['Estado', 'statuses']] as $key => [$label, $source]): ?><div><label for="report-<?= $key ?>"><?= $label ?></label><select id="report-<?= $key ?>" name="<?= $key ?>"><option value="">Todas</option><?php foreach ($filterOptions[$source] as $option): ?><option value="<?= (int) $option['id'] ?>" <?= (string) ($filters[$key] ?? '') === (string) $option['id'] ? 'selected' : '' ?>><?= $e($option['name']) ?></option><?php endforeach; ?></select></div><?php endforeach; ?><details class="report-more"><summary>Más filtros</summary><div><label for="report-search">Código o asunto</label><input id="report-search" name="search" maxlength="100" value="<?= $e((string) ($filters['search'] ?? '')) ?>"><label for="report-priority">Prioridad</label><select id="report-priority" name="priority"><option value="">Todas</option><?php foreach ($filterOptions['priorities'] as $option): ?><option value="<?= (int) $option['id'] ?>" <?= (string) ($filters['priority'] ?? '') === (string) $option['id'] ? 'selected' : '' ?>><?= $e($option['name']) ?></option><?php endforeach; ?></select><label for="report-assignment">Asignación</label><select id="report-assignment" name="assignment"><option value="">Todas</option><option value="assigned" <?= ($filters['assignment'] ?? '') === 'assigned' ? 'selected' : '' ?>>Asignadas</option><option value="unassigned" <?= ($filters['assignment'] ?? '') === 'unassigned' ? 'selected' : '' ?>>Sin asignar</option></select><?php require __DIR__ . '/partials/csi-report-extra-filters.php'; ?></div></details><button class="report-apply" type="submit">Aplicar</button><details class="report-export"><summary>Exportar reporte</summary><div><a href="/csi/reports.csv<?= $e($exportSuffix) ?>">Descargar CSV</a><a href="/csi/reports.pdf<?= $e($exportSuffix) ?>">Descargar PDF</a></div></details></div><div class="report-filters__bottom"><span>Períodos rápidos</span><a href="<?= $e($quickUrl($today->modify('first day of this month')->format('Y-m-d'), $today->format('Y-m-d'))) ?>">Este mes</a><a href="<?= $e($quickUrl($today->modify('first day of last month')->format('Y-m-d'), $today->modify('last day of last month')->format('Y-m-d'))) ?>">Mes anterior</a><a href="<?= $e($quickUrl($today->modify('first day of -2 months')->format('Y-m-d'), $today->format('Y-m-d'))) ?>">Últimos 3 meses</a><a href="<?= $e($quickUrl($today->modify('-14 days')->format('Y-m-d'), $today->format('Y-m-d'))) ?>">Esta quincena</a><span class="report-period-label">Datos del <?= $e($start->format('d/m/Y')) ?> al <?= $e($end->format('d/m/Y')) ?></span><a class="report-clear" href="/csi/reports">Limpiar filtros</a></div><?php if ($filterErrors !== []): ?><p class="report-error" role="alert"><?= $e(implode(' ', $filterErrors)) ?></p><?php endif; ?></form>
<?php if ($filterErrors === []): ?><section class="report-kpis" aria-label="Indicadores del período"><article><span>▤</span><div><strong><?= (int) $summary['total'] ?></strong><b>Solicitudes recibidas</b><small>Registradas durante el período</small></div></article><article><span>✓</span><div><strong><?= $resolved ?></strong><b>Solucionadas o cerradas</b><small>Registradas durante el período</small></div></article><article><span>▣</span><div><strong><?= $pending ?></strong><b>Pendientes al corte</b><small>Registradas durante el período</small></div></article><article><span>◷</span><div><strong><?= $inProgress ?></strong><b>En atención</b><small>En curso al momento de la consulta</small></div></article></section>
<?php if ($tab === 'summary'): ?><div class="report-grid report-grid--three"><section class="report-card"><h2>Evolución de solicitudes</h2><p>Recibidas y actualmente solucionadas según fecha de registro.</p><div class="report-legend"><span>● Recibidas</span><span>● Solucionadas</span></div><div class="report-chart" role="img" aria-label="Solicitudes por intervalo"><?php foreach ($bins as $bin): ?><div><span class="report-chart__bars"><i style="height:<?= 100 * $bin['received'] / $maxBin ?>%" title="<?= $bin['received'] ?> recibidas"></i><i style="height:<?= 100 * $bin['resolved'] / $maxBin ?>%" title="<?= $bin['resolved'] ?> solucionadas"></i></span><small><?= $e($bin['label']) ?></small></div><?php endforeach; ?></div></section><section class="report-card"><h2>Situación de las solicitudes al corte</h2><p>Estado actual de las solicitudes registradas en el período.</p><div class="report-status-bar" role="img" aria-label="Distribución por estado"><?php foreach ($summary['statuses'] as $status): ?><span style="width:<?= $summary['total'] > 0 ? 100 * $status['total'] / $summary['total'] : 0 ?>%;background:<?= $statusColors[$status['code']] ?? '#9aaeb9' ?>"></span><?php endforeach; ?></div><ul class="report-status-list"><?php foreach ($summary['statuses'] as $status): ?><li><i style="background:<?= $statusColors[$status['code']] ?? '#9aaeb9' ?>"></i><span><?= $e($status['name']) ?></span><b><?= (int) $status['total'] ?></b><small><?= $summary['total'] > 0 ? number_format(100 * $status['total'] / $summary['total'], 1, ',', '') : '0,0' ?> %</small></li><?php endforeach; ?></ul></section><section class="report-card"><h2>Solicitudes por tipo de problema</h2><p>Categorías con más incidencias.</p><ul class="report-rank"><?php foreach (array_slice($categories, 0, 5, true) as $name => $count): ?><li><div><span><?= $e($name) ?></span><b><?= $count ?> · <?= $summary['total'] > 0 ? number_format(100 * $count / $summary['total'], 1, ',', '') : '0,0' ?> %</b></div><i><span style="width:<?= 100 * $count / $maxCategory ?>%"></span></i></li><?php endforeach; ?></ul></section></div><div class="report-grid report-grid--two"><section class="report-card"><h2>Oficinas con mayor cantidad de solicitudes</h2><p>Dependencias con más incidencias en el período.</p><table class="report-table"><thead><tr><th>N.º</th><th>Oficina</th><th>Solicitudes</th><th>Participación</th></tr></thead><tbody><?php $rank = 0; foreach (array_slice($areas, 0, 5, true) as $name => $count): $rank++; ?><tr><td><?= $rank ?></td><th scope="row"><?= $e($name) ?></th><td><?= $count ?></td><td><span class="report-meter"><i style="width:<?= 100 * $count / $maxArea ?>%"></i></span><?= $summary['total'] > 0 ? number_format(100 * $count / $summary['total'], 1, ',', '') : '0,0' ?> %</td></tr><?php endforeach; ?></tbody></table><a href="<?= $e($tabUrl('office')) ?>">Ver análisis por oficina →</a></section><section class="report-card"><h2>Análisis del período</h2><p>Observaciones calculadas de los registros filtrados.</p><div class="report-observations"><?php if ($summary['total'] === 0): ?><p>No hay solicitudes en este período.</p><?php else: ?><p><strong>Tipo más frecuente</strong><?= $e((string) array_key_first($categories)) ?> reúne <?= current($categories) ?> solicitudes.</p><p><strong>Oficina con mayor demanda</strong><?= $e((string) array_key_first($areas)) ?> registra <?= current($areas) ?> solicitudes.</p><p><strong>Intervalo con más registros</strong><?php $peak = array_search(max(array_column($bins, 'received')), array_column($bins, 'received'), true); ?><?= $e($bins[$peak]['label']) ?> registra <?= $bins[$peak]['received'] ?> solicitudes.</p><?php endif; ?></div></section></div>
<?php elseif ($tab === 'attention'): ?><section class="report-card"><h2>Atenciones registradas</h2><p>Últimas diez solicitudes del filtro. Abre el expediente para consultar su historial.</p><div class="report-table-wrap"><table class="report-table"><thead><tr><th>Código</th><th>Problema</th><th>Oficina</th><th>Estado</th><th>Responsable</th></tr></thead><tbody><?php foreach ($recent as $row): ?><tr><th scope="row"><a href="/csi/requests/<?= rawurlencode($row['public_code']) ?>"><?= $e($row['public_code']) ?></a></th><td><?= $e($row['title']) ?></td><td><?= $e($row['area_name']) ?></td><td><?= $e($row['status_name']) ?></td><td><?= $e($row['technician_name'] ?? 'Sin asignar') ?></td></tr><?php endforeach; ?></tbody></table></div></section>
<?php else: ?><?php $breakdown = $tab === 'office' ? $areas : ($tab === 'category' ? $categories : $people); $label = $tab === 'office' ? 'Oficina' : ($tab === 'category' ? 'Tipo de problema' : 'Personal'); $maximum = max(1, ...array_values($breakdown)); ?><section class="report-card"><h2>Solicitudes por <?= mb_strtolower($label) ?></h2><p>Distribución de las <?= (int) $summary['total'] ?> solicitudes filtradas.</p><div class="report-table-wrap"><table class="report-table"><thead><tr><th><?= $e($label) ?></th><th>Solicitudes</th><th>Participación</th></tr></thead><tbody><?php foreach ($breakdown as $name => $count): ?><tr><th scope="row"><?= $e($name) ?></th><td><?= $count ?></td><td><span class="report-meter"><i style="width:<?= 100 * $count / $maximum ?>%"></i></span><?= $summary['total'] > 0 ? number_format(100 * $count / $summary['total'], 1, ',', '') : '0,0' ?> %</td></tr><?php endforeach; ?></tbody></table></div></section><?php endif; ?><?php endif; ?>
</main></body></html>
